#!/usr/bin/env python3
"""Deterministic compiler for program and release experience design trees.

The authored Markdown tree is the source. Generated registries are disposable
views. This compiler owns initialization, identity, inheritance, placement,
closure, coverage, structural limits, approval stamping and artifact promotion.
It is stdlib-only and emits stable findings sorted by path and check id.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import subprocess
import sys
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path

DEFAULT_SCHEMA = (Path(__file__).resolve().parent.parent / "skill-content"
                  / "experience-modeling" / "data" / "experience-schema.json")
GENERATED = "_generated"
MARKER = "<!-- generated by experience_compile render; do not edit by hand -->"
SLUG = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
RELATION_START = "## Related knowledge <!-- sec: relations:generated:start -->"
RELATION_END = "<!-- sec: relations:generated:end -->"
STRUCTURAL_START = "## Contents <!-- sec: structural:generated:start -->"
STRUCTURAL_END = "<!-- sec: structural:generated:end -->"


@dataclass(frozen=True)
class Finding:
    path: str
    check: str
    message: str


def fail(message: str, code: int = 1) -> int:
    print(f"experience_compile: {message}", file=sys.stderr)
    return code


def load_json(path: Path) -> dict:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"cannot read JSON {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise ValueError(f"JSON object required: {path}")
    return value


def schema_for(path: str) -> dict:
    schema = load_json(Path(path) if path else DEFAULT_SCHEMA)
    if schema.get("schema_version") != 2:
        raise ValueError("unsupported experience schema")
    return schema


def canonical(value) -> bytes:
    return (json.dumps(value, sort_keys=True, separators=(",", ":"),
                       ensure_ascii=False) + "\n").encode()


def sha(value: bytes) -> str:
    return "sha256:" + hashlib.sha256(value).hexdigest()


def frontmatter(path: Path) -> tuple[dict, str]:
    text = path.read_text(encoding="utf-8")
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        raise ValueError("missing frontmatter")
    data: dict = {}
    current = None
    end = None
    for number, raw in enumerate(lines[1:], 1):
        value = raw.strip()
        if value == "---":
            end = number + 1
            break
        if not value or value.startswith("#"):
            continue
        if value.startswith("- ") and current:
            data[current].append(value[2:].strip().strip("\"'"))
        elif ":" in value:
            key, _, scalar = value.partition(":")
            key, scalar = key.strip(), scalar.strip().strip("\"'")
            if not scalar:
                data[key] = []
                current = key
            else:
                current = None
                if scalar.startswith("["):
                    try:
                        data[key] = json.loads(scalar)
                    except json.JSONDecodeError:
                        data[key] = scalar
                elif scalar.isdigit():
                    data[key] = int(scalar)
                else:
                    data[key] = scalar
        else:
            raise ValueError(f"unparseable frontmatter line {number + 1}")
    if end is None:
        raise ValueError("unterminated frontmatter")
    return data, "\n".join(lines[end:]).strip() + "\n"


def write_note(path: Path, fields: dict, title: str, body: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        raise ValueError(f"refusing to overwrite {path}")
    fields = dict(fields)
    fields.setdefault("title", title)
    fields.setdefault("tags", [f"doc/{fields.get('type', 'experience')}"] +
                      ([f"status/{fields['status']}"] if fields.get("status") else []))
    rows = ["---"]
    for key, value in fields.items():
        if isinstance(value, list):
            rows.append(f"{key}:")
            rows.extend(
                f'  - "{item}"' if isinstance(item, str)
                and item.startswith("[[") and item.endswith("]]" )
                else f"  - {item}"
                for item in value
            )
        else:
            rows.append(f"{key}: {value}")
    rows.extend(["---", "", f"# {title}", "", body.strip(), "",
                 "## Navigation <!-- sec: nav -->", "",
                 "[[maps/experience-design|Experience Design]]", ""])
    path.write_text("\n".join(rows), encoding="utf-8")


def frontmatter_rows(fields: dict) -> list[str]:
    rows = ["---"]
    for key, value in fields.items():
        if isinstance(value, list):
            rows.append(f"{key}:")
            rows.extend(
                f'  - "{item}"' if isinstance(item, str)
                and item.startswith("[[") and item.endswith("]]" )
                else f"  - {item}"
                for item in value
            )
        else:
            rows.append(f"{key}: {value}")
    rows.append("---")
    return rows


def rewrite_note(path: Path, fields: dict, body: str) -> None:
    rows = frontmatter_rows(fields)
    rows.extend(["", body.rstrip(), ""])
    path.write_text("\n".join(rows), encoding="utf-8")


def program_dir(root: Path, program: str) -> Path:
    return root / "programs" / program.lower()


def release_dir(root: Path, program: str, release: str) -> Path:
    return program_dir(root, program) / "releases" / release.lower()


def authored_files(root: Path) -> list[Path]:
    return sorted(path for path in root.rglob("*.md")
                  if GENERATED not in path.parts and path.name != ".gitkeep")


def source_hash(root: Path) -> str:
    digest = hashlib.sha256()
    for path in authored_files(root):
        digest.update(path.relative_to(root).as_posix().encode())
        digest.update(b"\0")
        text = path.read_text(encoding="utf-8")
        text = re.sub(
            r"\n*" + re.escape(RELATION_START) + r".*?"
            + re.escape(RELATION_END) + r"\n*", "\n", text,
            flags=re.DOTALL,
        )
        text = re.sub(
            r"\n*" + re.escape(STRUCTURAL_START) + r".*?"
            + re.escape(STRUCTURAL_END) + r"\n*", "\n", text,
            flags=re.DOTALL,
        )
        digest.update(text.encode())
        digest.update(b"\0")
    return "sha256:" + digest.hexdigest()


def project_config(path: Path) -> dict:
    for parent in (path, *path.parents):
        candidate = parent / "config.json"
        if candidate.is_file():
            try:
                value = json.loads(candidate.read_text(encoding="utf-8"))
            except json.JSONDecodeError:
                return {}
            return value if isinstance(value, dict) else {}
    return {}


def reconcile_vault_navigation(root: Path) -> None:
    vault = root.parent
    map_path = vault / "maps" / "experience-design.md"
    map_path.parent.mkdir(parents=True, exist_ok=True)
    links = []
    candidates = [root / "experience.md"]
    candidates.extend(sorted(root.glob("programs/prg-*/program.md")))
    for note in candidates:
        if not note.is_file():
            continue
        rel = note.relative_to(vault).with_suffix("").as_posix()
        try:
            title = str(frontmatter(note)[0].get("title", note.stem))
        except ValueError:
            title = note.stem
        links.append(f"- [[{rel}|{title}]]")
    marker_start = "<!-- experience_compile map:start -->"
    marker_end = "<!-- experience_compile map:end -->"
    block = "\n".join([marker_start, *links, marker_end])
    if map_path.is_file():
        text = map_path.read_text(encoding="utf-8")
        if marker_start in text and marker_end in text:
            text = text[:text.index(marker_start)] + block + text[text.index(marker_end) + len(marker_end):]
        else:
            text = text.rstrip() + "\n\n" + block + "\n"
    else:
        text = ("---\ntype: moc\ntitle: Experience Design\ntags:\n"
                "  - doc/moc\n---\n\n# Experience Design\n\n" + block + "\n")
    map_path.write_text(text, encoding="utf-8")
    home = vault / "home.md"
    if home.is_file():
        text = home.read_text(encoding="utf-8")
        link = "[[maps/experience-design|Experience Design]]"
        if link not in text:
            home.write_text(text.rstrip() + "\n\n- " + link + "\n", encoding="utf-8")


def experience_parent(note: Path, root: Path) -> Path | None:
    rel = note.relative_to(root)
    parts = rel.parts
    if note.name == "program.md":
        return None
    if note.name == "release.md":
        return note.parents[2] / "program.md"
    if note.name == "space.md":
        return next((parent / "release.md" for parent in note.parents
                     if (parent / "release.md").is_file()), None)
    if note.name == "domain.md":
        parent_domain = note.parent.parent.parent / "domain.md"
        if parent_domain.is_file():
            return parent_domain
        return note.parent.parent.parent / "space.md"
    if any(value in parts for value in (
            "journeys", "flows", "screens", "artifacts", "reviews")):
        owner = note.parent.parent
        return owner_note_for(owner)
    return None


def replace_generated_section(text: str, block: str) -> str:
    if STRUCTURAL_START in text and STRUCTURAL_END in text:
        begin = text.index(STRUCTURAL_START)
        finish = text.index(STRUCTURAL_END, begin) + len(STRUCTURAL_END)
        text = text[:begin].rstrip() + text[finish:]
    if not block:
        return text.rstrip() + "\n"
    nav = "## Navigation <!-- sec: nav -->"
    if nav in text:
        before, after = text.split(nav, 1)
        return before.rstrip() + "\n\n" + block + "\n\n" + nav + after
    return text.rstrip() + "\n\n" + block + "\n"


def render_experience_navigation(root: Path) -> None:
    docs = root.parent
    notes = authored_files(root)
    children: dict[Path, list[Path]] = {}
    for note in notes:
        parent = experience_parent(note, root)
        if parent is not None and parent.is_file():
            children.setdefault(parent, []).append(note)
    navigation_root = docs / "maps" / "_navigation" / "experience-design"
    if navigation_root.exists():
        shutil.rmtree(navigation_root)
    for parent, values in sorted(children.items(), key=lambda item: str(item[0])):
        links = []
        for child in sorted(values):
            fm, _ = frontmatter(child)
            target = child.relative_to(docs).with_suffix("").as_posix()
            label = str(fm.get("title", child.stem))
            links.append(f"- [[{target}|{label}]]")
        block_rows: list[str] = []
        if len(links) <= 100:
            block_rows = links
        else:
            key = hashlib.sha256(
                parent.relative_to(root).as_posix().encode()).hexdigest()[:12]
            catalog_dir = navigation_root / key
            catalog_dir.mkdir(parents=True, exist_ok=True)
            for index in range(0, len(links), 100):
                number = index // 100 + 1
                catalog = catalog_dir / f"children-{number:03d}.md"
                catalog.write_text(
                    MARKER + "\n# Structural children\n\n"
                    + "\n".join(links[index:index + 100]) + "\n",
                    encoding="utf-8")
                target = catalog.relative_to(docs).with_suffix("").as_posix()
                block_rows.append(
                    f"- [[{target}|Children {number:03d}]]")
        block = "\n".join([STRUCTURAL_START, *block_rows, STRUCTURAL_END])
        current = parent.read_text(encoding="utf-8")
        rendered = replace_generated_section(current, block)
        if rendered != current:
            parent.write_text(rendered, encoding="utf-8")


def expected_owner(scopes: list[str]) -> Path:
    parsed = []
    for scope in scopes:
        space, marker, tail = scope.partition("#domains/")
        domains = tail.split("/domains/") if marker else []
        parsed.append((space, domains))
    spaces = {item[0] for item in parsed}
    if len(spaces) != 1:
        return Path(".")
    space = parsed[0][0]
    if not all(item[1] for item in parsed):
        return Path("spaces") / space
    common = list(parsed[0][1])
    for _, domains in parsed[1:]:
        common = common[:next((i for i, pair in enumerate(zip(common, domains))
                               if pair[0] != pair[1]), min(len(common), len(domains)))]
    owner = Path("spaces") / space
    for domain in common:
        owner = owner / "domains" / domain
    return owner


def docs_root_for_release(release: Path) -> Path:
    return release.parents[4]


def ba_scope_wikilink(release: Path, scope: str) -> str:
    space, marker, tail = scope.partition("#domains/")
    path = f"business-analysis/{space}"
    if marker:
        for domain in tail.split("/domains/"):
            path += f"/domains/{domain}"
        path += "/domain"
    else:
        path += "/space"
    return f"[[{path}|{scope}]]"


def ba_criterion_wikilink(release: Path, qualified: str) -> str:
    space, marker, ident = qualified.partition(":")
    if not marker:
        raise ValueError(f"criterion must be qualified: {qualified}")
    registry = load_json(
        docs_root_for_release(release) / "business-analysis" / space
        / GENERATED / "registry.json")
    info = (registry.get("ids") or {}).get(ident)
    if not isinstance(info, dict) or not isinstance(info.get("doc"), str):
        raise ValueError(f"criterion is absent from BA registry: {qualified}")
    target = f"business-analysis/{space}/{info['doc'][:-3]}"
    return f"[[{target}|{qualified}]]"


def ensure_scope_projections(release: Path, scopes: list[str], args) -> None:
    for scope in scopes:
        space, marker, tail = scope.partition("#domains/")
        space_note = release / "spaces" / space / "space.md"
        if not space_note.exists():
            write_note(space_note, {
                "type": "experience-space", "analysis_node": space,
                "analysis_revision": args.analysis_revision,
                "analysis_hash": args.analysis_hash,
                "criterion_set": args.criterion_set,
                "experience_coverage": [], "status": "draft",
                "derives_from": [ba_scope_wikilink(release, space)],
            }, f"{space.replace('-', ' ').title()} Experience Space",
                "Projection of the approved analysis node; do not copy BA prose.")
        if not marker:
            continue
        parent = release / "spaces" / space
        prefix = space
        for index, domain in enumerate(tail.split("/domains/")):
            parent = parent / "domains" / domain
            prefix += (f"#domains/{domain}" if index == 0
                       else f"/domains/{domain}")
            note = parent / "domain.md"
            if not note.exists():
                write_note(note, {
                    "type": "experience-domain", "analysis_node": prefix,
                    "analysis_revision": args.analysis_revision,
                    "analysis_hash": args.analysis_hash,
                    "criterion_set": args.criterion_set,
                    "experience_coverage": [], "status": "draft",
                    "derives_from": [ba_scope_wikilink(release, prefix)],
                }, f"{domain.replace('-', ' ').title()} Experience Domain",
                    "Projection of the approved analysis node; do not copy BA prose.")


def record_from(path: Path, release: Path, schema: dict) -> tuple[dict | None, list[Finding]]:
    findings: list[Finding] = []
    rel = path.relative_to(release).as_posix()
    try:
        fm, _ = frontmatter(path)
    except (OSError, ValueError) as exc:
        return None, [Finding(rel, "frontmatter", str(exc))]
    doc_type = str(fm.get("type", ""))
    if doc_type not in {
        "release", "experience-space", "experience-domain", "journey",
        "flow-set", "screen", "challenge-record", "artifact-manifest",
    }:
        return None, [Finding(rel, "document_type", f"unsupported type {doc_type!r}")]
    schema_type = doc_type.replace("-", "_")
    expected_name = schema["doc_types"].get(schema_type, {}).get("filename")
    suffix = schema["doc_types"].get(schema_type, {}).get("suffix")
    if expected_name and path.name != expected_name:
        findings.append(Finding(rel, "filename", f"{doc_type} must be named {expected_name}"))
    if suffix and (not path.name.endswith(suffix) or not SLUG.fullmatch(path.name[:-len(suffix)])):
        findings.append(Finding(rel, "filename", f"{doc_type} must use <slug>{suffix}"))
    if suffix and path.parent.name != schema["doc_types"][schema_type]["directory"]:
        findings.append(Finding(rel, "path", f"{doc_type} must be under {schema['doc_types'][schema_type]['directory']}/"))
    if doc_type in {"journey", "flow-set", "screen"}:
        ident = str(fm.get("id", ""))
        if not re.fullmatch(schema["id_patterns"][schema_type], ident):
            findings.append(Finding(rel, "id_shape", f"invalid {doc_type} id {ident!r}"))
        revision = fm.get("revision")
        if not isinstance(revision, int) or revision < 1:
            findings.append(Finding(rel, "revision", "revision must be a positive integer"))
        scopes = fm.get("analysis_scopes", [])
        if not isinstance(scopes, list) or not scopes:
            findings.append(Finding(rel, "scope", "analysis_scopes must be a non-empty list"))
        else:
            for value in scopes:
                if not re.fullmatch(schema["scope_pattern"], str(value)):
                    findings.append(Finding(rel, "scope", f"invalid canonical scope {value!r}"))
            owner = expected_owner([str(value) for value in scopes])
            actual_owner = path.parent.parent.relative_to(release)
            if actual_owner != owner:
                findings.append(Finding(rel, "lca", f"scope owner is {owner.as_posix()}, not {actual_owner.as_posix()}"))
            derived_aliases = {
                str(value).partition("|")[2].removesuffix("]]" )
                for value in fm.get("derives_from", [])
                if isinstance(value, str) and "|" in value
            }
            missing_scopes = sorted(set(map(str, scopes)) - derived_aliases)
            if missing_scopes:
                findings.append(Finding(
                    rel, "analysis_traceability",
                    "analysis scopes lack derives_from links: "
                    + ", ".join(missing_scopes)))
        criteria = fm.get("criterion_refs", [])
        if isinstance(criteria, list) and criteria:
            satisfied_aliases = {
                str(value).partition("|")[2].removesuffix("]]" )
                for value in fm.get("satisfies", [])
                if isinstance(value, str) and "|" in value
            }
            missing_criteria = sorted(set(map(str, criteria)) - satisfied_aliases)
            if missing_criteria:
                findings.append(Finding(
                    rel, "criterion_traceability",
                    "criteria lack satisfies links: "
                    + ", ".join(missing_criteria)))
        if doc_type == "screen" and not fm.get("uses_design"):
            findings.append(Finding(
                rel, "design_traceability", "screen must declare uses_design"))
    if doc_type in {"experience-space", "experience-domain"}:
        for key in ("analysis_node", "analysis_revision", "analysis_hash",
                    "criterion_set", "experience_coverage"):
            if key not in fm:
                findings.append(Finding(rel, "analysis_projection", f"missing {key}"))
        if fm.get("analysis_hash") and not re.fullmatch(r"sha256:[0-9a-f]{64}", str(fm["analysis_hash"])):
            findings.append(Finding(rel, "analysis_projection", "analysis_hash must be SHA-256"))
        analysis_node = str(fm.get("analysis_node", ""))
        space = analysis_node.partition("#domains/")[0]
        try:
            docs = release.parents[4]
            registry_path = docs / "business-analysis" / space / GENERATED / "registry.json"
            registry_bytes = registry_path.read_bytes()
            registry = json.loads(registry_bytes)
            expected_hash = "sha256:" + hashlib.sha256(registry_bytes).hexdigest()
            if fm.get("analysis_hash") != expected_hash:
                findings.append(Finding(rel, "analysis_projection", "approved BA registry hash is stale"))
            if doc_type == "experience-domain":
                expected_node = analysis_node.partition("#")[2]
                if expected_node and expected_node not in set(registry.get("codes", {}).values()):
                    findings.append(Finding(rel, "analysis_projection", "analysis domain is absent from the BA registry"))
            criteria = fm.get("criterion_set", [])
            if isinstance(criteria, list):
                known = set(registry.get("ids", {}))
                for criterion in criteria:
                    prefix, marker, ident = str(criterion).partition(":")
                    if not marker or prefix != space or ident not in known:
                        findings.append(Finding(rel, "analysis_projection", f"criterion is absent from approved BA registry: {criterion}"))
        except (OSError, json.JSONDecodeError, AttributeError):
            findings.append(Finding(rel, "analysis_projection", "approved BA registry is missing or unreadable"))
    if doc_type == "artifact-manifest":
        for key in (
            "artifact_path", "artifact_owner", "program_id", "release_id",
            "revision", "declared_ids", "related_to", "status",
        ):
            if key not in fm:
                findings.append(Finding(
                    rel, "artifact_manifest", f"missing {key}"))
        status = str(fm.get("status", ""))
        if status not in {"draft", "approved"}:
            findings.append(Finding(
                rel, "artifact_manifest", "status must be draft or approved"))
        if status == "approved":
            for key in ("artifact_sha256", "registry_hash", "approved_at_utc"):
                if key not in fm:
                    findings.append(Finding(
                        rel, "artifact_manifest", f"approved artifact missing {key}"))
            if fm.get("artifact_sha256") and not re.fullmatch(
                    r"sha256:[0-9a-f]{64}", str(fm["artifact_sha256"])):
                findings.append(Finding(
                    rel, "artifact_manifest", "artifact_sha256 must be SHA-256"))
        artifact_path = str(fm.get("artifact_path", ""))
        if artifact_path != path.with_name(
                path.name.removesuffix("-artifact.md") + "-preview.html"
        ).relative_to(release).as_posix():
            findings.append(Finding(
                rel, "artifact_manifest",
                "artifact_path must identify the sibling preview HTML"))
        declared = fm.get("declared_ids")
        if not isinstance(declared, list):
            findings.append(Finding(
                rel, "artifact_manifest", "declared_ids must be a list"))
    return {"path": rel, **fm}, findings


def compile_release(release: Path, schema: dict) -> tuple[dict, list[Finding]]:
    findings: list[Finding] = []
    note = release / "release.md"
    if not note.is_file():
        return {}, [Finding("release.md", "layout", "missing release.md")]
    try:
        release_fm, _ = frontmatter(note)
    except ValueError as exc:
        return {}, [Finding("release.md", "frontmatter", str(exc))]
    records: list[dict] = []
    projected_criteria: set[str] = set()
    identities: dict[tuple[str, int], str] = {}
    latest: dict[str, int] = {}
    for path in authored_files(release):
        record, local = record_from(path, release, schema)
        findings.extend(local)
        if record and record.get("type") in {"journey", "flow-set", "screen"}:
            key = (str(record.get("id", "")), int(record.get("revision", 0) or 0))
            if key in identities:
                findings.append(Finding(record["path"], "id_unique", f"duplicate identity {key[0]}@r{key[1]}"))
            identities[key] = record["path"]
            latest[key[0]] = max(latest.get(key[0], 0), key[1])
            records.append(record)
        if record and record.get("type") in {
                "experience-space", "experience-domain"}:
            values = record.get("criterion_set", [])
            if isinstance(values, list):
                projected_criteria.update(str(value) for value in values)
        if record and record.get("approved_at_utc"):
            try:
                approved = datetime.fromisoformat(
                    str(record["approved_at_utc"]).replace("Z", "+00:00"))
                if approved > datetime.now(timezone.utc):
                    findings.append(Finding(
                        record["path"], "future_timestamp",
                        "approved_at_utc is in the future"))
            except ValueError:
                findings.append(Finding(
                    record["path"], "future_timestamp",
                    "approved_at_utc is not ISO-8601"))
    program = str(release_fm.get("program_id", ""))
    rel_id = str(release_fm.get("release_id", ""))
    if not re.fullmatch(schema["program_pattern"], program):
        findings.append(Finding("release.md", "program_identity", "invalid program_id"))
    if not re.fullmatch(schema["release_pattern"], rel_id):
        findings.append(Finding("release.md", "release_identity", "invalid release_id"))
    refs = set()
    declared_states, declared_transitions = set(), set()
    state_graph: dict[str, set[str]] = {}
    covered_criteria: set[str] = set(str(value) for value in release_fm.get("non_ui_criteria", []) if isinstance(release_fm.get("non_ui_criteria", []), list))
    for record in records:
        for key in ("journey_refs", "flow_refs", "screen_refs"):
            values = record.get(key, [])
            if isinstance(values, list):
                refs.update(str(value) for value in values)
        values = record.get("criterion_refs", [])
        if isinstance(values, list):
            covered_criteria.update(str(value) for value in values)
        for value in record.get("states", []) if isinstance(record.get("states", []), list) else []:
            value = str(value)
            if not re.fullmatch(schema["id_patterns"]["state"], value):
                findings.append(Finding(record["path"], "id_shape", f"invalid state id {value!r}"))
            if value in declared_states:
                findings.append(Finding(record["path"], "id_unique", f"duplicate state id {value}"))
            declared_states.add(value)
        for value in record.get("transitions", []) if isinstance(record.get("transitions", []), list) else []:
            value = str(value)
            if not re.fullmatch(schema["id_patterns"]["transition"], value):
                findings.append(Finding(record["path"], "id_shape", f"invalid transition id {value!r}"))
            if value in declared_transitions:
                findings.append(Finding(record["path"], "id_unique", f"duplicate transition id {value}"))
            declared_transitions.add(value)
        for key in ("from_state", "to_state"):
            if record.get(key):
                refs.add(str(record[key]))
        for edge in record.get("edges", []) if isinstance(record.get("edges", []), list) else []:
            left, marker, right = str(edge).partition(">")
            if not marker or not left or not right:
                findings.append(Finding(record["path"], "transition_edge", f"invalid edge {edge!r}"))
                continue
            refs.update((left, right))
            state_graph.setdefault(left, set()).add(right)
    ids = set(latest) | declared_states | declared_transitions
    for ref in sorted(refs - ids):
        findings.append(Finding("release.md", "closure", f"dangling experience id {ref}"))
    def graph_cycle():
        visiting, visited, stack = set(), set(), []
        def walk(node):
            if node in visiting:
                return stack[stack.index(node):] + [node]
            if node in visited:
                return []
            visiting.add(node); stack.append(node)
            for target in sorted(state_graph.get(node, set())):
                found = walk(target)
                if found: return found
            stack.pop(); visiting.remove(node); visited.add(node)
            return []
        for node in sorted(state_graph):
            found = walk(node)
            if found: return found
        return []
    cycle = graph_cycle()
    if cycle:
        findings.append(Finding("release.md", "graph_cycle", "transition cycle: " + " -> ".join(cycle)))
    for criterion in sorted(projected_criteria - covered_criteria):
        findings.append(Finding("release.md", "criterion_coverage", f"criterion has no UI or non-UI disposition: {criterion}"))
    config = project_config(release)
    overrides = config.get("limits", {}) if isinstance(config.get("limits", {}), dict) else {}
    flow_limit = int(overrides.get("experience_flows_per_set", schema["limits"]["flows_per_set"]))
    transition_limit = int(overrides.get("experience_transitions_per_set", schema["limits"]["transitions_per_set"]))
    screen_limit = int(overrides.get("experience_screens_per_leaf_domain", schema["limits"]["screens_per_leaf_domain"]))
    scale = str(release_fm.get("scale", "small"))
    if config.get("scale") and config.get("scale") != scale:
        findings.append(Finding("release.md", "scale", f"release scale {scale} differs from project scale {config.get('scale')}"))
    multiplier = schema["scale_multipliers"].get(scale.replace("-", "_"), 1)
    for record in records:
        if record.get("type") == "flow-set":
            effective_flow = flow_limit if "experience_flows_per_set" in overrides else flow_limit * multiplier
            effective_transition = transition_limit if "experience_transitions_per_set" in overrides else transition_limit * multiplier
            if len(record.get("flows", [])) > effective_flow:
                findings.append(Finding(record["path"], "structural_limit", "flow-set exceeds effective flow limit"))
            if len(record.get("transitions", [])) > effective_transition:
                findings.append(Finding(record["path"], "structural_limit", "flow-set exceeds effective transition limit"))
    by_owner: dict[str, int] = {}
    for record in records:
        if record.get("type") == "screen":
            owner = str(Path(record["path"]).parent.parent)
            by_owner[owner] = by_owner.get(owner, 0) + 1
    for owner, count in sorted(by_owner.items()):
        effective_screen = screen_limit if "experience_screens_per_leaf_domain" in overrides else screen_limit * multiplier
        if count > effective_screen:
            findings.append(Finding(owner, "structural_limit", "leaf owner exceeds effective screen limit"))
    inherited_records: list[dict] = []
    inherits = str(release_fm.get("inherits", ""))
    if inherits:
        current_number = int(rel_id.split("-")[-1]) if rel_id.split("-")[-1].isdigit() else 0
        inherited_number = int(inherits.split("-")[-1]) if inherits.split("-")[-1].isdigit() else 0
        if inherited_number >= current_number:
            findings.append(Finding("release.md", "inheritance", "a release may inherit only an earlier release"))
        inherited_path = release.parent / inherits.lower() / GENERATED / "effective-registry.json"
        try:
            inherited = load_json(inherited_path)
            inherited_records = list(inherited.get("records", []))
        except ValueError as exc:
            findings.append(Finding("release.md", "inheritance", str(exc)))
        local_by_id = {str(item.get("id")): item for item in records}
        for old in inherited_records:
            ident = str(old.get("id", ""))
            if ident not in local_by_id:
                inherited_copy = dict(old)
                inherited_copy["inherited_from"] = inherits
                records.append(inherited_copy)
                continue
            new = local_by_id[ident]
            old_revision = int(old.get("revision", 0))
            if int(new.get("revision", 0)) <= old_revision:
                findings.append(Finding(new["path"], "inheritance", "changed record must increase revision"))
            exact = f"{program}:{ident}@r{old_revision}"
            if str(new.get("supersedes", "")) != exact:
                findings.append(Finding(new["path"], "inheritance", f"changed record must supersede {exact}"))
    artifacts = []
    registered_artifact_paths: set[str] = set()
    for manifest in sorted(release.rglob("*-artifact.md")):
        if "artifacts" not in manifest.parts:
            continue
        try:
            manifest_fm, _ = frontmatter(manifest)
        except (OSError, ValueError):
            continue
        artifact_rel = str(manifest_fm.get("artifact_path", ""))
        artifact = (release / artifact_rel).resolve()
        try:
            artifact.relative_to(release.resolve())
        except ValueError:
            findings.append(Finding(
                manifest.relative_to(release).as_posix(),
                "artifact_ownership", "artifact path escapes the release"))
            continue
        registered_artifact_paths.add(artifact_rel)
        if not artifact.is_file() or artifact.suffix.lower() != ".html":
            findings.append(Finding(
                manifest.relative_to(release).as_posix(),
                "artifact_ownership", "manifest preview HTML is missing"))
            continue
        owner = manifest.parent.parent
        owner_note = next(
            (owner / name for name in ("domain.md", "space.md", "release.md")
             if (owner / name).is_file()), None)
        manifest_target = manifest.relative_to(
            docs_root_for_release(release)).with_suffix("").as_posix()
        manifest_link = f"[[{manifest_target}|"
        if owner_note is None or manifest_link not in owner_note.read_text(
                encoding="utf-8"):
            findings.append(Finding(
                manifest.relative_to(release).as_posix(),
                "artifact_ownership",
                "owning node note does not reference the artifact manifest"))
        if manifest_fm.get("status") != "approved":
            continue
        digest = sha(artifact.read_bytes())
        if manifest_fm.get("artifact_sha256") != digest:
            findings.append(Finding(
                manifest.relative_to(release).as_posix(),
                "artifact_ownership", "artifact SHA-256 is stale"))
        artifacts.append({
            "manifest": manifest.relative_to(release).as_posix(),
            "path": artifact_rel,
            "sha256": digest,
            "owner": str(manifest_fm.get("artifact_owner", "")),
            "declared_ids": sorted(str(value) for value in
                                   manifest_fm.get("declared_ids", [])
                                   if isinstance(value, str)),
        })
    for artifact in sorted(release.rglob("*-preview.html")):
        if ("artifacts" in artifact.parts
                and artifact.relative_to(release).as_posix()
                not in registered_artifact_paths):
            findings.append(Finding(
                artifact.relative_to(release).as_posix(),
                "artifact_ownership", "preview has no artifact manifest"))
    registry = {
        "schema_version": 2,
        "program_id": program,
        "release_id": rel_id,
        "inherits": inherits,
        "source_hash": source_hash(release),
        "records": sorted(records, key=lambda value: (value.get("id", ""), value.get("revision", 0))),
        "artifacts": artifacts,
    }
    # The model registry hash excludes artifact bytes so an approved preview
    # can embed that hash while its own SHA-256 is attached to the registry
    # without a circular hash dependency.
    registry["registry_hash"] = sha(canonical({
        key: value for key, value in registry.items()
        if key not in {"artifacts", "source_hash"}
    }))
    generated = release / GENERATED / "effective-registry.json"
    if generated.is_file():
        try:
            current = load_json(generated)
            if current != registry:
                findings.append(Finding(f"{GENERATED}/effective-registry.json", "generated_freshness", "generated registry is stale or tampered"))
        except ValueError as exc:
            findings.append(Finding(f"{GENERATED}/effective-registry.json", "generated_freshness", str(exc)))
    return registry, findings


def compile_program(directory: Path, schema: dict) -> tuple[dict, list[Finding]]:
    findings: list[Finding] = []
    note = directory / "program.md"
    if not note.is_file():
        return {}, [Finding("program.md", "layout", "missing program.md")]
    try:
        program_fm, _ = frontmatter(note)
    except ValueError as exc:
        return {}, [Finding("program.md", "frontmatter", str(exc))]
    program_id = str(program_fm.get("program_id", ""))
    if not re.fullmatch(schema["program_pattern"], program_id):
        findings.append(Finding("program.md", "program_identity", "invalid program_id"))
    releases: list[dict] = []
    coverage: dict[str, list[str]] = {}
    release_root = directory / "releases"
    release_dirs = sorted(path for path in release_root.glob("rel-*") if path.is_dir())
    if not release_dirs:
        findings.append(Finding("releases", "program_closure", "program has no releases"))
    for release in release_dirs:
        compiled, local = compile_release(release, schema)
        for finding in local:
            findings.append(Finding(
                f"releases/{release.name}/{finding.path}",
                finding.check,
                finding.message,
            ))
        try:
            release_fm, _ = frontmatter(release / "release.md")
        except (OSError, ValueError):
            release_fm = {}
        release_id = str(compiled.get("release_id", release_fm.get("release_id", "")))
        if compiled.get("program_id") and compiled.get("program_id") != program_id:
            findings.append(Finding(
                f"releases/{release.name}/release.md",
                "program_identity",
                "release belongs to a different program",
            ))
        generated = release / GENERATED / "effective-registry.json"
        if not generated.is_file():
            findings.append(Finding(
                f"releases/{release.name}/{GENERATED}/effective-registry.json",
                "generated_freshness",
                "release render is required before program compilation",
            ))
        releases.append({
            "release_id": release_id,
            "status": str(release_fm.get("status", "")),
            "challenge_status": str(release_fm.get("challenge_status", "")),
            "inherits": str(compiled.get("inherits", "")),
            "registry_hash": str(compiled.get("registry_hash", "")),
        })
        for record in compiled.get("records", []):
            if not isinstance(record, dict):
                continue
            for criterion in record.get("criterion_refs", []) \
                    if isinstance(record.get("criterion_refs", []), list) else []:
                coverage.setdefault(str(criterion), []).append(
                    f"{release_id}:{record.get('id', '')}@r{record.get('revision', '')}"
                )
        non_ui = release_fm.get("non_ui_criteria", [])
        if isinstance(non_ui, list):
            for criterion in non_ui:
                coverage.setdefault(str(criterion), []).append(f"{release_id}:non-ui")
    registry = {
        "schema_version": 2,
        "program_id": program_id,
        "source_hash": source_hash(directory),
        "releases": releases,
        "coverage": {key: sorted(set(value)) for key, value in sorted(coverage.items())},
    }
    registry["registry_hash"] = sha(canonical({
        key: value for key, value in registry.items() if key != "source_hash"
    }))
    generated = directory / GENERATED / "program-registry.json"
    if generated.is_file():
        try:
            current = load_json(generated)
            if current != registry:
                findings.append(Finding(
                    f"{GENERATED}/program-registry.json",
                    "generated_freshness",
                    "generated program registry is stale or tampered",
                ))
        except ValueError as exc:
            findings.append(Finding(
                f"{GENERATED}/program-registry.json", "generated_freshness", str(exc)
            ))
    return registry, findings


def print_findings(findings: list[Finding], as_json: bool) -> int:
    ordered = sorted(set(findings), key=lambda item: (item.path, item.check, item.message))
    if as_json:
        print(json.dumps({"ok": not ordered, "findings": [item.__dict__ for item in ordered]}, indent=2))
    else:
        for item in ordered:
            print(f"ERROR {item.path}:1 [{item.check}] {item.message}")
    return 1 if ordered else 0


def cmd_init_program(args) -> int:
    schema = schema_for(args.schema)
    if not re.fullmatch(schema["program_pattern"], args.program):
        return fail("invalid program id", 2)
    root = Path(args.root).resolve()
    directory = program_dir(root, args.program)
    directory.mkdir(parents=True, exist_ok=True)
    if not (root / "experience.md").exists():
        write_note(root / "experience.md", {"type": "experience", "status": "draft"}, "Experience Design", "Program map. Add links when the first program is born.")
    note = directory / "program.md"
    if not note.exists():
        fields = {"type": "program", "program_id": args.program,
                  "status": "draft"}
        if args.scope:
            fields["derives_from"] = [
                ba_scope_wikilink(directory / "releases" / "rel-000", scope)
                for scope in args.scope]
        if args.constrained_by:
            fields["constrained_by"] = args.constrained_by
        write_note(note, fields, args.title or args.program,
                   "Program intent, release strategy and approval record.")
    (directory / "releases").mkdir(exist_ok=True)
    (directory / GENERATED).mkdir(exist_ok=True)
    reconcile_vault_navigation(root)
    print(directory)
    return 0


def cmd_init_release(args) -> int:
    schema = schema_for(args.schema)
    if not re.fullmatch(schema["program_pattern"], args.program) or not re.fullmatch(schema["release_pattern"], args.release):
        return fail("invalid program or release id", 2)
    root = Path(args.root).resolve()
    program_note = program_dir(root, args.program) / "program.md"
    if not program_note.is_file():
        return fail("initialize the program first")
    directory = release_dir(root, args.program, args.release)
    directory.mkdir(parents=True, exist_ok=True)
    note = directory / "release.md"
    if not note.exists():
        program_fm, program_body = frontmatter(program_note)
        if program_fm.get("status") == "approved":
            prior_hash = str(program_fm.get("registry_hash", ""))
            program_fm["status"] = "draft"
            if prior_hash:
                program_fm["supersedes_registry_hash"] = prior_hash
            for key in (
                "approved_at_utc", "registry_hash", "challenge_status",
                "challenge_hash",
            ):
                program_fm.pop(key, None)
            tags = program_fm.get("tags", [])
            if isinstance(tags, list):
                program_fm["tags"] = [
                    value for value in tags
                    if not str(value).startswith("status/")
                ] + ["status/draft"]
            rewrite_note(program_note, program_fm, program_body)
        fields = {"type": "release", "program_id": args.program,
                  "release_id": args.release, "status": "draft", "scale": args.scale}
        if args.inherits:
            fields["inherits"] = args.inherits
        if args.scope:
            fields["derives_from"] = [
                ba_scope_wikilink(directory, scope) for scope in args.scope]
        if args.constrained_by:
            fields["constrained_by"] = args.constrained_by
        write_note(note, fields, args.title or args.release, "Release scope, experience delta and gate record.")
    for child in ("spaces", "journeys", "screens", "artifacts", "reviews", GENERATED):
        (directory / child).mkdir(exist_ok=True)
    print(directory)
    return 0


def cmd_stub(args) -> int:
    schema = schema_for(args.schema)
    release = Path(args.release_root).resolve()
    scopes = [value.strip() for value in args.scope if value.strip()]
    if not scopes:
        return fail("at least one --scope is required", 2)
    owner = expected_owner(scopes)
    ensure_scope_projections(release, scopes, args)
    if args.kind not in {"journey", "flow-set", "screen"}:
        return fail("unsupported stub kind", 2)
    schema_kind = args.kind.replace("-", "_")
    if not re.fullmatch(schema["id_patterns"][schema_kind], args.id):
        return fail("invalid stable id", 2)
    spec = schema["doc_types"][schema_kind]
    directory = release / owner / spec["directory"]
    filename = args.slug + spec["suffix"]
    fields = {"type": args.kind, "id": args.id, "revision": args.revision,
              "status": "draft", "analysis_scopes": scopes,
              "criterion_refs": args.criterion_set,
              "derives_from": [ba_scope_wikilink(release, value)
                               for value in scopes]}
    if args.criterion_set:
        fields["satisfies"] = [
            ba_criterion_wikilink(release, value)
            for value in args.criterion_set
        ]
    for key in ("uses_design", "constrained_by"):
        values = getattr(args, key)
        if values:
            if any(not (value.startswith("[[") and value.endswith("]]"))
                   for value in values):
                return fail(f"--{key.replace('_', '-')} requires a full wikilink", 2)
            fields[key] = values
    if args.supersedes:
        fields["supersedes"] = args.supersedes
    write_note(directory / filename, fields, args.title or args.id,
               "Define the bounded experience behavior and exact references.")
    print(directory / filename)
    return 0


def release_arg(args) -> Path:
    if args.release_root:
        return Path(args.release_root).resolve()
    if not (args.root and args.program and args.release):
        raise ValueError("use --release-root or --root with --program and --release")
    return release_dir(Path(args.root).resolve(), args.program, args.release)


def program_mode(args) -> bool:
    return bool(args.root and args.program and not args.release and not args.release_root)


def program_arg(args) -> Path:
    if not (args.root and args.program):
        raise ValueError("program compilation requires --root and --program")
    return program_dir(Path(args.root).resolve(), args.program)


def artifact_gate_findings(release: Path, registry: dict) -> list[Finding]:
    findings: list[Finding] = []
    known = {str(item.get("id", "")) for item in registry.get("records", [])}
    for item in registry.get("records", []):
        if not isinstance(item, dict):
            continue
        known.update(str(value) for value in item.get("states", [])
                     if isinstance(item.get("states", []), list))
        known.update(str(value) for value in item.get("transitions", [])
                     if isinstance(item.get("transitions", []), list))
    for artifact in sorted(release.rglob("*-preview.html")):
        if "artifacts" not in artifact.parts:
            continue
        manifest = artifact.with_name(
            artifact.name.removesuffix("-preview.html") + "-artifact.md")
        try:
            manifest_fm, _ = frontmatter(manifest)
        except (OSError, ValueError):
            manifest_fm = {}
        if manifest_fm.get("status") != "approved":
            findings.append(Finding(
                artifact.relative_to(release).as_posix(),
                "artifact_gate", "artifact is still draft",
            ))
            continue
        declared = sorted(str(value) for value in
                          manifest_fm.get("declared_ids", [])
                          if isinstance(value, str))
        for ident in sorted(set(declared) - known):
            findings.append(Finding(
                artifact.relative_to(release).as_posix(),
                "artifact_identity",
                f"artifact declares an id absent from the effective registry: {ident}",
            ))
        command = [
            sys.executable, str(Path(__file__).with_name("experience_artifact_check.py")),
            "--artifact", str(artifact), "--release-root", str(release),
            "--manifest", str(manifest),
            "--registry", str(release / GENERATED / "effective-registry.json"),
            "--owner", artifact.parent.parent.relative_to(release).as_posix(),
            "--json",
        ]
        for ident in declared:
            command.extend(("--declared-id", ident))
        try:
            completed = subprocess.run(
                command, capture_output=True, text=True, check=False, timeout=30,
            )
            payload = json.loads(completed.stdout)
            for message in payload.get("findings", []):
                findings.append(Finding(
                    artifact.relative_to(release).as_posix(),
                    "artifact_gate", str(message),
                ))
        except (OSError, subprocess.TimeoutExpired, json.JSONDecodeError) as exc:
            findings.append(Finding(
                artifact.relative_to(release).as_posix(),
                "artifact_gate", f"artifact verifier failed: {exc}",
            ))
    return findings


def cmd_check(args) -> int:
    schema = schema_for(args.schema)
    if program_mode(args):
        directory = program_arg(args)
        registry, findings = compile_program(directory, schema)
        if args.gate:
            try:
                gate_fm = frontmatter(directory / "program.md")[0]
            except (OSError, ValueError):
                gate_fm = {}
            if gate_fm.get("status") != "approved":
                findings.append(Finding("program.md", "program_gate", "program status is not approved"))
            elif gate_fm.get("registry_hash") != registry.get("registry_hash"):
                findings.append(Finding("program.md", "program_gate", "approved program registry hash is stale"))
            if gate_fm.get("challenge_status") != "approved" \
                    or not str(gate_fm.get("challenge_hash", "")).startswith("sha256:"):
                findings.append(Finding("program.md", "challenge_gate", "approved challenge evidence is missing"))
            for release in registry.get("releases", []):
                if release.get("status") != "approved" \
                        or release.get("challenge_status") != "approved":
                    findings.append(Finding(
                        f"releases/{str(release.get('release_id', '')).lower()}/release.md",
                        "release_gate",
                        "every release must be approved before the program gate",
                    ))
            if not (directory / GENERATED / "program-registry.json").is_file():
                findings.append(Finding(
                    f"{GENERATED}/program-registry.json",
                    "generated_freshness",
                    "program render is required before gate",
                ))
        if args.json and not findings:
            print(json.dumps({"ok": True, "registry_hash": registry.get("registry_hash"), "findings": []}, indent=2))
            return 0
        return print_findings(findings, args.json)
    try:
        release = release_arg(args)
    except ValueError as exc:
        return fail(str(exc), 2)
    registry, findings = compile_release(release, schema)
    if args.gate:
        findings.extend(artifact_gate_findings(release, registry))
        status = ""
        try:
            status = str(frontmatter(release / "release.md")[0].get("status", ""))
        except (OSError, ValueError):
            pass
        if status != "approved":
            findings.append(Finding("release.md", "release_gate", "release status is not approved"))
        try:
            gate_fm = frontmatter(release / "release.md")[0]
        except (OSError, ValueError):
            gate_fm = {}
        if gate_fm.get("status") == "approved" \
                and gate_fm.get("registry_hash") != registry.get("registry_hash"):
            findings.append(Finding("release.md", "release_gate", "approved release registry hash is stale"))
        if gate_fm.get("challenge_status") != "approved" or not str(gate_fm.get("challenge_hash", "")).startswith("sha256:"):
            findings.append(Finding("release.md", "challenge_gate", "approved challenge evidence is missing"))
        if not (release / GENERATED / "effective-registry.json").is_file():
            findings.append(Finding(f"{GENERATED}/effective-registry.json", "generated_freshness", "render is required before gate"))
    if args.json and not findings:
        print(json.dumps({"ok": True, "registry_hash": registry.get("registry_hash"), "findings": []}, indent=2))
        return 0
    return print_findings(findings, args.json)


def cmd_render(args) -> int:
    schema = schema_for(args.schema)
    if program_mode(args):
        directory = program_arg(args)
        render_experience_navigation(directory.parent.parent)
        registry, findings = compile_program(directory, schema)
        hard = [item for item in findings if item.check != "generated_freshness"]
        if hard:
            return print_findings(hard, False)
        generated = directory / GENERATED
        generated.mkdir(exist_ok=True)
        (generated / "program-registry.json").write_bytes(canonical(registry))
        matrix = [MARKER, "# Release Matrix", "", "| Release | Status | Inherits | Registry |", "|---|---|---|---|"]
        matrix.extend(
            f"| {item['release_id']} | {item['status']} | {item['inherits'] or '-'} | `{item['registry_hash']}` |"
            for item in registry["releases"]
        )
        (generated / "release-matrix.md").write_text("\n".join(matrix) + "\n", encoding="utf-8")
        coverage = [MARKER, "# Program Experience Coverage", ""]
        coverage.extend(
            f"- `{criterion}`: {', '.join(refs)}"
            for criterion, refs in registry["coverage"].items()
        )
        (generated / "coverage.md").write_text("\n".join(coverage) + "\n", encoding="utf-8")
        status = [MARKER, "# Program Experience Status", "",
                  f"- Source hash: `{registry['source_hash']}`",
                  f"- Registry hash: `{registry['registry_hash']}`",
                  f"- Releases: {len(registry['releases'])}", ""]
        (generated / "status.md").write_text("\n".join(status), encoding="utf-8")
        reconcile_vault_navigation(directory.parent.parent)
        print(registry["registry_hash"])
        return 0
    try:
        release = release_arg(args)
    except ValueError as exc:
        return fail(str(exc), 2)
    render_experience_navigation(release.parents[3])
    registry, findings = compile_release(release, schema)
    hard = [item for item in findings if item.check != "generated_freshness"]
    if hard:
        return print_findings(hard, False)
    generated = release / GENERATED
    generated.mkdir(exist_ok=True)
    (generated / "effective-registry.json").write_bytes(canonical(registry))
    scope_map: dict[str, list[str]] = {}
    criteria: dict[str, list[str]] = {}
    for record in registry["records"]:
        for scope in record.get("analysis_scopes", []):
            scope_map.setdefault(str(scope), []).append(str(record.get("id", "")))
        for criterion in record.get("criterion_refs", []):
            criteria.setdefault(str(criterion), []).append(str(record.get("id", "")))
    (generated / "scope-map.json").write_bytes(canonical({"schema_version": 1, "scopes": scope_map}))
    coverage = [MARKER, "# Experience Coverage", ""]
    coverage.extend(f"- `{key}`: {', '.join(sorted(values))}" for key, values in sorted(criteria.items()))
    (generated / "coverage.md").write_text("\n".join(coverage) + "\n", encoding="utf-8")
    status = [MARKER, "# Experience Status", "", f"- Source hash: `{registry['source_hash']}`", f"- Registry hash: `{registry['registry_hash']}`", f"- Records: {len(registry['records'])}", ""]
    (generated / "status.md").write_text("\n".join(status), encoding="utf-8")
    reconcile_vault_navigation(release.parents[3])
    print(registry["registry_hash"])
    return 0


def cmd_resolve(args) -> int:
    schema = schema_for(args.schema)
    registry, findings = compile_release(release_arg(args), schema)
    if findings and any(item.check != "generated_freshness" for item in findings):
        return print_findings(findings, False)
    matches = [item for item in registry["records"] if item.get("id") == args.id]
    if args.revision:
        matches = [item for item in matches if item.get("revision") == args.revision]
    if not matches:
        return fail(f"unknown id {args.id}")
    print(json.dumps(matches, indent=2))
    return 0


def cmd_diff(args) -> int:
    current = load_json(Path(args.current))
    previous = load_json(Path(args.previous))
    key = lambda item: (item.get("id"), item.get("revision"))
    old = {key(item): item for item in previous.get("records", [])}
    new = {key(item): item for item in current.get("records", [])}
    print(json.dumps({"added": [new[k] for k in sorted(new.keys() - old.keys())],
                      "removed": [old[k] for k in sorted(old.keys() - new.keys())],
                      "unchanged": len(new.keys() & old.keys())}, indent=2))
    return 0


def cmd_stamp(args) -> int:
    is_program = program_mode(args)
    directory = program_arg(args) if is_program else release_arg(args)
    registry_name = "program-registry.json" if is_program else "effective-registry.json"
    note_name = "program.md" if is_program else "release.md"
    registry = load_json(directory / GENERATED / registry_name)
    if registry.get("source_hash") != source_hash(directory):
        return fail("generated registry is stale")
    path = directory / note_name
    fm, body = frontmatter(path)
    if fm.get("status") == "approved":
        return fail(f"{'program' if is_program else 'release'} is already approved")
    fm["status"] = "approved"
    if not args.challenge_hash.startswith("sha256:"):
        return fail("stamp requires the compiler-verified challenge hash", 2)
    fm["challenge_status"] = "approved"
    fm["challenge_hash"] = args.challenge_hash
    tags = fm.get("tags", [])
    if isinstance(tags, list):
        fm["tags"] = [value for value in tags
                      if not str(value).startswith("status/")] + ["status/approved"]
    fm["approval_revision"] = int(fm.get("approval_revision", 0)) + 1
    fm["registry_hash"] = registry["registry_hash"]
    fm["approved_at_utc"] = datetime.now(timezone.utc).replace(
        microsecond=0).isoformat()
    rewrite_note(path, fm, body)
    cmd_render(args)
    return 0


def owner_note_for(owner: Path) -> Path | None:
    return next(
        (owner / name for name in ("domain.md", "space.md", "release.md")
         if (owner / name).is_file()), None)


def add_artifact_reference(owner_note: Path, manifest: Path,
                           release: Path, title: str) -> None:
    target = manifest.relative_to(
        docs_root_for_release(release)).with_suffix("").as_posix()
    link = f"[[{target}|{title}]]"
    text = owner_note.read_text(encoding="utf-8")
    if link in text:
        return
    section = "## Experience artifacts"
    nav = "## Navigation <!-- sec: nav -->"
    row = f"- {link}"
    if section in text:
        before, after = text.split(section, 1)
        text = before + section + after.rstrip() + "\n" + row + "\n"
    elif nav in text:
        before, after = text.split(nav, 1)
        text = before.rstrip() + f"\n\n{section}\n\n{row}\n\n{nav}" + after
    else:
        text = text.rstrip() + f"\n\n{section}\n\n{row}\n"
    owner_note.write_text(text, encoding="utf-8")


def artifact_context(args) -> tuple[Path, Path, Path, Path] | int:
    release = release_arg(args)
    if not SLUG.fullmatch(args.package):
        return fail("package must be a kebab-case slug", 2)
    owner = (release / Path(args.owner)).resolve()
    try:
        owner.relative_to(release)
    except ValueError:
        return fail("owner escapes release", 2)
    owner_note = owner_note_for(owner)
    if owner_note is None:
        return fail("owner must contain release.md, space.md or domain.md", 2)
    artifact = owner / "artifacts" / f"{args.package}-preview.html"
    manifest = owner / "artifacts" / f"{args.package}-artifact.md"
    return release, owner_note, artifact, manifest


def cmd_init_artifact(args) -> int:
    context = artifact_context(args)
    if isinstance(context, int):
        return context
    release, owner_note, artifact, manifest = context
    registry = load_json(release / GENERATED / "effective-registry.json")
    if registry.get("source_hash") != source_hash(release):
        return fail("effective registry is stale; render before artifact init")
    if artifact.exists() or manifest.exists():
        return fail("artifact already exists; use a new package name")
    artifact.parent.mkdir(parents=True, exist_ok=True)
    artifact.write_text(
        "<!doctype html>\n<html lang=\"en\">\n<head>\n"
        "<meta charset=\"utf-8\">\n"
        f"<meta name=\"experience-program\" content=\"{registry['program_id']}\">\n"
        f"<meta name=\"experience-release\" content=\"{registry['release_id']}\">\n"
        f"<meta name=\"experience-registry-hash\" content=\"{registry['registry_hash']}\">\n"
        f"<title>{args.title or args.package.replace('-', ' ').title()}</title>\n"
        "</head>\n<body>\n<!-- Author the bounded preview here. -->\n"
        "</body>\n</html>\n",
        encoding="utf-8",
    )
    owner_target = owner_note.relative_to(
        docs_root_for_release(release)).with_suffix("").as_posix()
    owner_fm, _ = frontmatter(owner_note)
    owner_alias = str(owner_fm.get("title", owner_note.stem))
    owner_link = f"[[{owner_target}|{owner_alias}]]"
    title = args.title or f"{args.package.replace('-', ' ').title()} Artifact"
    write_note(manifest, {
        "type": "artifact-manifest", "status": "draft",
        "program_id": registry["program_id"],
        "release_id": registry["release_id"], "revision": args.revision,
        "artifact_path": artifact.relative_to(release).as_posix(),
        "artifact_owner": owner_link, "declared_ids": [],
        "related_to": [owner_link],
    }, title, f"[Open draft preview]({artifact.name})")
    add_artifact_reference(owner_note, manifest, release, title)
    print(json.dumps({
        "manifest": manifest.relative_to(release).as_posix(),
        "path": artifact.relative_to(release).as_posix(),
        "status": "draft",
    }, indent=2))
    return 0


def cmd_approve_artifact(args) -> int:
    context = artifact_context(args)
    if isinstance(context, int):
        return context
    release, _owner_note, artifact, manifest = context
    if not artifact.is_file() or not manifest.is_file():
        return fail("initialize the artifact before approval")
    manifest_fm, manifest_body = frontmatter(manifest)
    if manifest_fm.get("status") != "draft":
        return fail("only a draft artifact can be approved")
    schema = schema_for(args.schema)
    registry, compile_findings = compile_release(release, schema)
    hard = [item for item in compile_findings
            if item.check != "generated_freshness"]
    if hard:
        return print_findings(hard, False)
    candidate_text = artifact.read_text(encoding="utf-8")
    declared = sorted(set(re.findall(
        r'(?:id|data-experience-id)=["\']((?:JRN|FLW|SCR|STA|TRN)-[0-9]{3,})["\']',
        candidate_text,
    )))
    known = {str(item.get("id", "")) for item in registry.get("records", [])}
    for item in registry.get("records", []):
        if isinstance(item, dict):
            known.update(str(value) for value in item.get("states", [])
                         if isinstance(item.get("states", []), list))
            known.update(str(value) for value in item.get("transitions", [])
                         if isinstance(item.get("transitions", []), list))
    unknown = sorted(set(declared) - known)
    if unknown:
        return fail("artifact declares unknown experience ids: "
                    + ", ".join(unknown))
    for key, expected in {
        "experience-program": registry.get("program_id"),
        "experience-release": registry.get("release_id"),
        "experience-registry-hash": registry.get("registry_hash"),
    }.items():
        match = re.search(
            rf'<meta\s+name=["\']{re.escape(key)}["\']\s+'
            rf'content=["\']([^"\']+)["\']', candidate_text)
        if not match or match.group(1) != expected:
            return fail(f"artifact metadata {key} does not match the registry")
    if re.search(r'(?:href|src)=["\'](?:https?:|ftp:|//)', candidate_text):
        return fail("artifact contains a remote request or asset")
    original = manifest.read_bytes()
    digest = sha(artifact.read_bytes())
    manifest_fm.update({
        "status": "approved", "registry_hash": registry["registry_hash"],
        "artifact_sha256": digest, "declared_ids": declared,
        "approved_at_utc": datetime.now(timezone.utc).replace(
            microsecond=0).isoformat(),
    })
    rewrite_note(
        manifest, manifest_fm,
        manifest_body.replace("Open draft preview", "Open approved preview"),
    )
    render_code = cmd_render(args)
    if render_code:
        manifest.write_bytes(original)
        cmd_render(args)
        return render_code
    verified = artifact_gate_findings(
        release, load_json(release / GENERATED / "effective-registry.json")
    )
    if verified:
        manifest.write_bytes(original)
        cmd_render(args)
        return print_findings(verified, False)
    print(json.dumps({
        "manifest": manifest.relative_to(release).as_posix(),
        "path": artifact.relative_to(release).as_posix(),
        "sha256": digest, "declared_ids": declared,
    }, indent=2))
    return 0


def add_release_locator(parser) -> None:
    parser.add_argument("--release-root", default="")
    parser.add_argument("--root", default="")
    parser.add_argument("--program", default="")
    parser.add_argument("--release", default="")
    parser.add_argument("--schema", default="")


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    p = sub.add_parser("init-program")
    p.add_argument("--root", required=True); p.add_argument("--program", required=True)
    p.add_argument("--title", default=""); p.add_argument("--scope", action="append", default=[])
    p.add_argument("--constrained-by", action="append", default=[])
    p.add_argument("--schema", default="")
    p.set_defaults(func=cmd_init_program)
    p = sub.add_parser("init-release")
    p.add_argument("--root", required=True); p.add_argument("--program", required=True)
    p.add_argument("--release", required=True); p.add_argument("--title", default="")
    p.add_argument("--inherits", default=""); p.add_argument("--scale", default="small")
    p.add_argument("--scope", action="append", default=[])
    p.add_argument("--constrained-by", action="append", default=[])
    p.add_argument("--schema", default=""); p.set_defaults(func=cmd_init_release)
    p = sub.add_parser("stub")
    p.add_argument("--release-root", required=True); p.add_argument("--kind", required=True)
    p.add_argument("--id", required=True); p.add_argument("--revision", type=int, default=1)
    p.add_argument("--slug", required=True); p.add_argument("--title", default="")
    p.add_argument("--scope", action="append", default=[]); p.add_argument("--supersedes", default="")
    p.add_argument("--analysis-revision", type=int, default=1)
    p.add_argument("--analysis-hash", default="sha256:" + "0" * 64)
    p.add_argument("--criterion-set", action="append", default=[])
    p.add_argument("--uses-design", action="append", default=[])
    p.add_argument("--constrained-by", action="append", default=[])
    p.add_argument("--schema", default=""); p.set_defaults(func=cmd_stub)
    for name, handler in (("check", cmd_check), ("render", cmd_render),
                          ("resolve", cmd_resolve), ("stamp", cmd_stamp)):
        p = sub.add_parser(name); add_release_locator(p)
        if name == "check":
            p.add_argument("--gate", action="store_true"); p.add_argument("--changed", action="store_true"); p.add_argument("--json", action="store_true")
        if name == "resolve":
            p.add_argument("--id", required=True); p.add_argument("--revision", type=int)
        if name == "stamp":
            p.add_argument("--challenge-hash", required=True)
        p.set_defaults(func=handler)
    p = sub.add_parser("diff"); p.add_argument("--previous", required=True); p.add_argument("--current", required=True); p.set_defaults(func=cmd_diff)
    for name, handler in (
        ("init-artifact", cmd_init_artifact),
        ("approve-artifact", cmd_approve_artifact),
    ):
        p = sub.add_parser(name); add_release_locator(p)
        p.add_argument("--owner", required=True)
        p.add_argument("--package", required=True)
        p.add_argument("--title", default="")
        p.add_argument("--revision", type=int, default=1)
        p.set_defaults(func=handler)
    return parser


def main(argv: list[str] | None = None) -> int:
    try:
        args = build_parser().parse_args(argv)
        return args.func(args)
    except ValueError as exc:
        return fail(str(exc), 2)


if __name__ == "__main__":
    raise SystemExit(main())
